    67	  return customerRecords.map(({ id, companyName, contactName, status, lastContactedAt }) => ({
    68	    id,
    69	    companyName,
    70	    contactName,
    71	    status,
    72	    lastContactedAt,
    73	  }));
    74	}
    75	
    76	export function getCustomerDetail(customerId: string): CustomerDetail | undefined {
    77	  const customer = customerRecords.find(({ id }) => id === customerId);
    78	  if (!customer) return undefined;
    79	
    80	  return {
    81	    id: customer.id,
    82	    companyName: customer.companyName,
    83	    contactName: customer.contactName,
    84	    email: customer.email,
    85	    phone: customer.phone,
    86	    status: customer.status,
    87	    note: customer.note,
    88	  };
    89	}
