    97	  if (options.simulateFailure) {
    98	    return { ok: false, reason: "削除に失敗しました。時間をおいて再試行してください。" };
    99	  }
   100	  const index = customerRecords.findIndex(({ id }) => id === customerId);
   101	  if (index < 0) {
   102	    return { ok: false, reason: "対象の顧客が見つかりません。" };
   103	  }
   104	  customerRecords.splice(index, 1);
   105	  return { ok: true };
   106	}
   107	
   108	export function resetCustomerRecords(): void {
   109	  customerRecords = initialCustomerRecords.map((record) => ({ ...record }));
   110	}
