     1	import { HashRouter, Link, Navigate, Route, Routes, useParams } from "react-router-dom";
     2	import { getCustomerDetail, listCustomerSummaries } from "./fixtures";
     3	
     4	function CustomerListPage() {
     5	  return (
     6	    <main>
     7	      <h1>顧客一覧</h1>
     8	      <ul>
     9	        {listCustomerSummaries().map((customer) => (
    10	          <li key={customer.id}>
    11	            <Link to={`/customers/${customer.id}`}>{customer.companyName}</Link>
    12	          </li>
    13	        ))}
    14	      </ul>
    15	    </main>
    16	  );
    17	}
    18	
    19	function CustomerDetailPage() {
    20	  const { customerId = "" } = useParams();
    21	  const customer = getCustomerDetail(customerId);
    22	
    23	  if (!customer) return <Navigate replace to="/customers" />;
    24	
    25	  return (
    26	    <main>
    27	      <Link to="/customers">顧客一覧へ戻る</Link>
    28	      <h1>{customer.companyName}</h1>
    29	      <p>brief.mdの要件に沿って、この詳細画面を実装してください。</p>
    30	    </main>
    31	  );
    32	}
    33	
    34	export function App() {
    35	  return (
    36	    <HashRouter>
    37	      <Routes>
    38	        <Route path="/customers" element={<CustomerListPage />} />
    39	        <Route path="/customers/:customerId" element={<CustomerDetailPage />} />
    40	        <Route path="*" element={<Navigate replace to="/customers" />} />
    41	      </Routes>
    42	    </HashRouter>
    43	  );
    44	}
