import "@testing-library/jest-dom/vitest";
import { render, screen, waitFor } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { App } from "./src/App";

const log: string[] = [];

describe("dbg2", () => {
  it("poll manually", async () => {
    window.location.hash = "#/customers/customer_northstar?state=loading";
    render(<App />);
    const t0 = Date.now();
    for (let i = 0; i < 40; i++) {
      const found = Array.from(document.querySelectorAll("button")).map((b) => b.textContent);
      log.push(`${Date.now() - t0}ms: ${JSON.stringify(found)}`);
      if (found.includes("保存中")) break;
      await new Promise((r) => setTimeout(r, 25));
    }
    (await import("node:fs")).writeFileSync("/tmp/dbg-poll.txt", log.join("\n"));
    expect(true).toBe(true);
  });

  it("poll inside waitFor", async () => {
    window.location.hash = "#/customers/customer_northstar?state=loading";
    render(<App />);
    const t0 = Date.now();
    const log2: string[] = [];
    try {
      await waitFor(() => {
        const found = Array.from(document.querySelectorAll("button")).map((b) => b.textContent);
        log2.push(`${Date.now() - t0}ms: ${JSON.stringify(found)}`);
        if (!found.includes("保存中")) throw new Error("not yet");
      }, { timeout: 1000 });
    } catch (e) {
      log2.push(`FAILED: ${(e as Error).message}`);
    }
    (await import("node:fs")).writeFileSync("/tmp/dbg-poll2.txt", log2.join("\n"));
    expect(true).toBe(true);
  });
});
EOF
